import{_ as a}from"./chunks/image-2.D4emUsw6.js";import{b as r,O as e,g as o,j as d}from"./chunks/framework.DcaUmd3X.js";const l="/assets/image.BgyRU2Cz.webp",s="/assets/image-1.DHfk_1VV.webp",k=JSON.parse('{"title":"第1章 · 认识 Oracle","description":"","frontmatter":{},"headers":[],"relativePath":"database/oracle/getting-started/what-is-oracle/index.md","filePath":"数据库管理/Oracle从入门到精通/1.入门准备/第1章·认识Oracle.md","lastUpdated":1783947942000}'),n={name:"database/oracle/getting-started/what-is-oracle/index.md"};function i(c,t,h,b,u,p){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="第1章-·-认识-oracle" tabindex="-1">第1章 · 认识 Oracle <a class="header-anchor" href="#第1章-·-认识-oracle" aria-label="Permalink to &quot;第1章 · 认识 Oracle&quot;">​</a></h1><h2 id="本章目标" tabindex="-1">本章目标 <a class="header-anchor" href="#本章目标" aria-label="Permalink to &quot;本章目标&quot;">​</a></h2><p>读完这一章，你会搞清楚三个问题：</p><ol><li><strong>数据库到底是什么？</strong> 为什么不用 Excel 存数据？</li><li><strong>Oracle 在这个江湖里是什么地位？</strong> 它跟 MySQL、SQL Server 有什么区别？</li><li><strong>E-R 图怎么画？</strong> 怎么用一张图设计出靠谱的数据库结构？</li></ol><p>另外，我们会引入一个<strong>贯穿全书的实战案例——学生选课管理系统</strong>，后面所有章节的 SQL 练习都会围绕它展开。</p><h2 id="_1-1-数据库是什么-为什么需要它" tabindex="-1">1.1 数据库是什么？为什么需要它？ <a class="header-anchor" href="#_1-1-数据库是什么-为什么需要它" aria-label="Permalink to &quot;1.1 数据库是什么？为什么需要它？&quot;">​</a></h2><h3 id="_1-1-1-没有数据库的世界" tabindex="-1">1.1.1 没有数据库的世界 <a class="header-anchor" href="#_1-1-1-没有数据库的世界" aria-label="Permalink to &quot;1.1.1 没有数据库的世界&quot;">​</a></h3><p>想象你在一所学校的教务处工作，学生信息记在一个 Excel 表格里：</p><table tabindex="0"><thead><tr><th>学号</th><th>姓名</th><th>性别</th><th>班级</th><th>选修课程</th></tr></thead><tbody><tr><td>2024001</td><td>张三</td><td>男</td><td>软件工程1班</td><td>Java程序设计, 数据库原理, 大学英语</td></tr><tr><td>2024002</td><td>李四</td><td>女</td><td>软件工程1班</td><td>数据库原理, 操作系统</td></tr><tr><td>2024003</td><td>王五</td><td>男</td><td>计算机科学2班</td><td>Java程序设计, 大学英语</td></tr></tbody></table><p>看起来还行？现在问题来了：</p><ul><li><strong>问题1</strong>：王五退学了，你要删掉他的记录。但 &quot;Java程序设计&quot; 和 &quot;大学英语&quot; 这两门课的选课人数就凭空少了一人，数据对不上了。</li><li><strong>问题2</strong>：张三的 &quot;选修课程&quot; 那一格塞了 3 门课，你想统计 &quot;有多少人选了数据库原理？&quot;——得用字符串匹配去搜，10 万条记录的时候 Excel 直接卡死。</li><li><strong>问题3</strong>：教务处主任和班主任同时打开这个文件修改，最后保存的人会覆盖掉前面人的修改——到底以谁的为准？</li></ul><p>这就是没有数据库时程序员们的日常痛苦。数据库的诞生，就是为了解决这三个核心问题。</p><h3 id="_1-1-2-数据库帮我们解决了什么" tabindex="-1">1.1.2 数据库帮我们解决了什么？ <a class="header-anchor" href="#_1-1-2-数据库帮我们解决了什么" aria-label="Permalink to &quot;1.1.2 数据库帮我们解决了什么？&quot;">​</a></h3><p>数据库（Database）本质上就是一个<strong>有组织、有纪律的数据仓库</strong>。相比 Excel 文件，它提供了四个核心能力：</p><table tabindex="0"><thead><tr><th>痛点</th><th>数据库的解决方案</th></tr></thead><tbody><tr><td>数据冗余、不一致</td><td><strong>数据完整性约束</strong>——一个数据只存一处，改一处全生效</td></tr><tr><td>查询效率低</td><td><strong>索引 + 查询优化器</strong>——百万级数据秒级返回</td></tr><tr><td>多人同时操作冲突</td><td><strong>事务 + 锁机制</strong>——每个人感觉自己独占数据库</td></tr><tr><td>数据安全问题</td><td><strong>权限系统</strong>——谁能看、谁能改，精确到列级别</td></tr></tbody></table><blockquote><p><strong>一句话总结</strong>：数据库 = 数据不丢（持久化）+ 数据不乱（一致性）+ 数据不冲突（并发控制）。</p></blockquote><h3 id="_1-1-3-常见术语-30-秒速览" tabindex="-1">1.1.3 常见术语 30 秒速览 <a class="header-anchor" href="#_1-1-3-常见术语-30-秒速览" aria-label="Permalink to &quot;1.1.3 常见术语 30 秒速览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>大白话解释</th></tr></thead><tbody><tr><td>数据库（Database）</td><td>存放数据的&quot;仓库&quot;，物理上是磁盘上的文件</td></tr><tr><td>表（Table）</td><td>仓库里的&quot;货架&quot;，数据按行列整齐摆放</td></tr><tr><td>行（Row / Record）</td><td>一条记录，比如&quot;张三&quot;的所有信息</td></tr><tr><td>列（Column / Field）</td><td>一个属性，比如&quot;姓名&quot;</td></tr><tr><td>SQL</td><td>跟数据库&quot;对话&quot;的语言，告诉它你要干什么</td></tr><tr><td>DBMS</td><td>数据库管理系统，Oracle、MySQL 都是 DBMS</td></tr></tbody></table><h2 id="_1-2-数据库的类型" tabindex="-1">1.2 数据库的类型 <a class="header-anchor" href="#_1-2-数据库的类型" aria-label="Permalink to &quot;1.2 数据库的类型&quot;">​</a></h2><p>市面上的数据库可以分成两大类：</p><h3 id="_1-2-1-关系型数据库-relational-database" tabindex="-1">1.2.1 关系型数据库（Relational Database） <a class="header-anchor" href="#_1-2-1-关系型数据库-relational-database" aria-label="Permalink to &quot;1.2.1 关系型数据库（Relational Database）&quot;">​</a></h3><p>把数据存进<strong>一张张有关联的表</strong>里，表之间通过<strong>外键</strong>建立联系。</p><p><img src="'+l+'" alt="alt text"></p><p>代表产品：<strong>Oracle、MySQL、SQL Server、PostgreSQL</strong></p><p>核心特点：</p><ul><li>数据按<strong>表</strong>组织，结构清晰</li><li>用 <strong>SQL</strong> 操作数据，标准化程度高</li><li>支持 <strong>ACID</strong> 事务（以后会细讲）</li></ul><h3 id="_1-2-2-非关系型数据库-nosql" tabindex="-1">1.2.2 非关系型数据库（NoSQL） <a class="header-anchor" href="#_1-2-2-非关系型数据库-nosql" aria-label="Permalink to &quot;1.2.2 非关系型数据库（NoSQL）&quot;">​</a></h3><p>不用表结构，数据以键值对、文档、图等形式存储。</p><p>代表产品：MongoDB（文档型）、Redis（键值型）、Neo4j（图数据库）</p><p>适用场景：数据结构不固定（如社交媒体动态）、需要极高并发读写（如秒杀系统）</p><blockquote><p>本教程讲的 Oracle 属于<strong>关系型数据库</strong>，目前全球银行、电信、政府等核心系统中使用最广泛的数据库。</p></blockquote><h2 id="_1-3-oracle-的江湖地位" tabindex="-1">1.3 Oracle 的江湖地位 <a class="header-anchor" href="#_1-3-oracle-的江湖地位" aria-label="Permalink to &quot;1.3 Oracle 的江湖地位&quot;">​</a></h2><h3 id="_1-3-1-发展简史" tabindex="-1">1.3.1 发展简史 <a class="header-anchor" href="#_1-3-1-发展简史" aria-label="Permalink to &quot;1.3.1 发展简史&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>里程碑</th></tr></thead><tbody><tr><td>1977</td><td>Larry Ellison 等三人创立 Software Development Laboratories（Oracle 前身）</td></tr><tr><td>1979</td><td>发布第一个商用 SQL 关系型数据库——比 IBM 还早</td></tr><tr><td>1983</td><td>公司改名为 Oracle，推出第 3 版，用 C 语言重写（可移植到不同操作系统）</td></tr><tr><td>1992</td><td>Oracle 7 发布——从此奠定企业级数据库霸主地位</td></tr><tr><td>2001</td><td>Oracle 9i——&quot;i&quot;代表 Internet，开始面向互联网</td></tr><tr><td>2003</td><td>Oracle 10g——&quot;g&quot;代表 Grid（网格计算），引入自动管理</td></tr><tr><td>2007</td><td>Oracle 11g——大量自动化特性，DBA 的日常管理大幅简化</td></tr><tr><td>2013</td><td>Oracle 12c——&quot;c&quot;代表 Cloud（云），引入 CDB/PDB 多租户架构</td></tr><tr><td>2019</td><td>Oracle 19c——12c 系列的最终长期支持版本</td></tr><tr><td>2023</td><td>Oracle 23ai——&quot;ai&quot;代表 AI，内置向量搜索和 AI 能力</td></tr></tbody></table><p>本教程以 <strong>Oracle 12c / 19c</strong> 为基础讲解，这两个版本是目前企业中使用最广泛的。</p><h3 id="_1-3-2-为什么大公司选-oracle" tabindex="-1">1.3.2 为什么大公司选 Oracle？ <a class="header-anchor" href="#_1-3-2-为什么大公司选-oracle" aria-label="Permalink to &quot;1.3.2 为什么大公司选 Oracle？&quot;">​</a></h3><ul><li><strong>可靠性</strong>：银行核心系统跑了几十年不丢一条数据</li><li><strong>并发能力</strong>：成千上万用户同时操作不卡顿（MVCC 机制，第17章细讲）</li><li><strong>安全性</strong>：细粒度权限控制，符合各种合规要求</li><li><strong>生态完善</strong>：配套的备份恢复（RMAN）、数据同步（Data Guard）、集群（RAC）一应俱全</li></ul><h2 id="_1-4-e-r-图-数据库设计的第一步" tabindex="-1">1.4 E-R 图：数据库设计的第一步 <a class="header-anchor" href="#_1-4-e-r-图-数据库设计的第一步" aria-label="Permalink to &quot;1.4 E-R 图：数据库设计的第一步&quot;">​</a></h2><p>在实际建表之前，你需要先画出<strong>数据之间的关系</strong>。这就是 E-R 图（Entity-Relationship Diagram，实体关系图）的任务。</p><h3 id="_1-4-1-三个基本元素" tabindex="-1">1.4.1 三个基本元素 <a class="header-anchor" href="#_1-4-1-三个基本元素" aria-label="Permalink to &quot;1.4.1 三个基本元素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>元素</th><th>画法</th><th>含义</th></tr></thead><tbody><tr><td><strong>实体（Entity）</strong></td><td>矩形框</td><td>一个&quot;东西&quot;——学生、课程、老师</td></tr><tr><td><strong>属性（Attribute）</strong></td><td>椭圆</td><td>实体有什么特征——学生的学号、姓名</td></tr><tr><td><strong>关系（Relationship）</strong></td><td>菱形</td><td>实体之间怎么关联——学生&quot;选修&quot;课程</td></tr></tbody></table><h3 id="_1-4-2-关系的三种-数量模式" tabindex="-1">1.4.2 关系的三种&quot;数量模式&quot; <a class="header-anchor" href="#_1-4-2-关系的三种-数量模式" aria-label="Permalink to &quot;1.4.2 关系的三种&quot;数量模式&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>表示</th><th>举例</th></tr></thead><tbody><tr><td><strong>一对一（1:1）</strong></td><td>1 ─── 1</td><td>一个学生有一张校园卡，一张卡只属于一个学生</td></tr><tr><td><strong>一对多（1:N）</strong></td><td>1 ─── N</td><td>一个班级有多个学生，一个学生只属于一个班级</td></tr><tr><td><strong>多对多（M:N）</strong></td><td>M ─── N</td><td>一个学生选多门课，一门课被多个学生选</td></tr></tbody></table><blockquote><p><strong>关键技巧</strong>：多对多关系在实际建表时，需要拆成<strong>一张中间表</strong>（也叫关联表）。比如 &quot;学生 M:N 课程&quot; 要拆成：学生（1）──（N）选课表（N）──（1）课程</p></blockquote><h3 id="_1-4-3-画一张-e-r-图" tabindex="-1">1.4.3 画一张 E-R 图 <a class="header-anchor" href="#_1-4-3-画一张-e-r-图" aria-label="Permalink to &quot;1.4.3 画一张 E-R 图&quot;">​</a></h3><p>我们以 &quot;学生选课系统&quot; 为例，分析一下需求：</p><ol><li>一个学生属于一个专业，一个专业有多个学生 → <strong>专业 1:N 学生</strong></li><li>一个学生可以选多门课，一门课可以被多个学生选 → <strong>学生 M:N 课程</strong></li><li>选课之后有成绩 → <strong>成绩是选课关系的属性</strong></li></ol><p>E-R 图如下：</p><p><img src="'+s+'" alt="alt text"></p><ul><li>学生和选课表是 <strong>1:N</strong> 关系：<strong>一个学生可以有多条选课记录</strong></li><li>课程和选课表是 <strong>1:N</strong> 关系：<strong>一门课程也可以被选多次</strong></li></ul><p>看，通过一张中间表 &quot;选课表&quot;，多对多关系就被消解成了两个一对多关系。这就是关系型数据库设计的核心思想。</p><blockquote><p><strong>为什么不用 &quot;选修课程&quot; 这一列直接存多门课？</strong></p><p>回到 1.1.1 节的 Excel 例子——把多门课塞进一个格子里，你没法用 SQL 高效查询。拆成多行之后，&quot;谁选了数据库原理？&quot; 就变成了简单的 <code>SELECT 学号 FROM 选课表 WHERE 课程编号 = &#39;C001&#39;</code>，数据库能瞬间返回结果。</p></blockquote><h2 id="_1-5-oracle-12c-体系结构速览" tabindex="-1">1.5 Oracle 12c 体系结构速览 <a class="header-anchor" href="#_1-5-oracle-12c-体系结构速览" aria-label="Permalink to &quot;1.5 Oracle 12c 体系结构速览&quot;">​</a></h2><p>在动手安装之前，先花 5 分钟看看 Oracle 的&quot;骨架&quot;。不用全记住，有个印象就行，第15章还会深入讲解。</p><h3 id="_1-5-1-实例-数据库-完整的-oracle" tabindex="-1">1.5.1 实例 + 数据库 = 完整的 Oracle <a class="header-anchor" href="#_1-5-1-实例-数据库-完整的-oracle" aria-label="Permalink to &quot;1.5.1 实例 + 数据库 = 完整的 Oracle&quot;">​</a></h3><p>Oracle 由两部分组成：</p><p><img src="'+a+`" alt="alt text"></p><ul><li><strong>实例（Instance）</strong> = 内存 + 后台进程，是&quot;干活&quot;的部分</li><li><strong>数据库（Database）</strong> = 磁盘上的物理文件，是&quot;存东西&quot;的部分</li></ul><blockquote><p>类比：实例就像 Word 程序，数据库就像 <code>.docx</code> 文件。你打开 Word（启动实例）来编辑文件（访问数据库）。</p></blockquote><h3 id="_1-5-2-内存结构-sga-和-pga" tabindex="-1">1.5.2 内存结构：SGA 和 PGA <a class="header-anchor" href="#_1-5-2-内存结构-sga-和-pga" aria-label="Permalink to &quot;1.5.2 内存结构：SGA 和 PGA&quot;">​</a></h3><p>Oracle 的内存分成两大块：</p><table tabindex="0"><thead><tr><th>内存区域</th><th>谁在用？</th><th>存什么？</th></tr></thead><tbody><tr><td><strong>SGA</strong>（系统全局区）</td><td>所有人共享</td><td>SQL 执行计划、数据缓存、日志缓冲</td></tr><tr><td><strong>PGA</strong>（程序全局区）</td><td>每个连接独享</td><td>排序临时空间、会话信息</td></tr></tbody></table><h3 id="_1-5-3-进程结构-前台和后台" tabindex="-1">1.5.3 进程结构：前台和后台 <a class="header-anchor" href="#_1-5-3-进程结构-前台和后台" aria-label="Permalink to &quot;1.5.3 进程结构：前台和后台&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>用户进程</strong></td><td>你在 SQL*Plus 里敲的命令，就是通过用户进程发到 Oracle 的</td></tr><tr><td><strong>服务器进程</strong></td><td>接收用户进程的请求，执行 SQL，返回结果</td></tr><tr><td><strong>后台进程</strong></td><td>默默在后台干活：DBWn 写数据、LGWR 写日志、SMON 做保洁……</td></tr></tbody></table><h3 id="_1-5-4-存储结构-从大到小" tabindex="-1">1.5.4 存储结构：从大到小 <a class="header-anchor" href="#_1-5-4-存储结构-从大到小" aria-label="Permalink to &quot;1.5.4 存储结构：从大到小&quot;">​</a></h3><p>Oracle 的存储层次像一个俄罗斯套娃：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数据库</span></span>
<span class="line"><span>  └── 表空间（Tablespace）  ← 最大的逻辑存储单位</span></span>
<span class="line"><span>        └── 段（Segment）    ← 一张表就是一个段</span></span>
<span class="line"><span>              └── 区（Extent）   ← 连续的一组数据块</span></span>
<span class="line"><span>                    └── 块（Block）   ← 最小的存储单位（默认 8KB）</span></span></code></pre></div><blockquote><p>不要被这些名词吓到。你现在只需要知道：<strong>数据最终存在数据块里，表空间是管理这些数据块的最大容器</strong>。</p></blockquote><h2 id="_1-6-本教程的-主线剧情-学生选课管理系统" tabindex="-1">1.6 本教程的&quot;主线剧情&quot;：学生选课管理系统 <a class="header-anchor" href="#_1-6-本教程的-主线剧情-学生选课管理系统" aria-label="Permalink to &quot;1.6 本教程的&quot;主线剧情&quot;：学生选课管理系统&quot;">​</a></h2><p>为了让你学到的东西能马上用起来，全书的所有示例都围绕一个真实场景——<strong>学生选课管理系统</strong>来展开。</p><h3 id="涉及的数据表" tabindex="-1">涉及的数据表 <a class="header-anchor" href="#涉及的数据表" aria-label="Permalink to &quot;涉及的数据表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表名</th><th>说明</th></tr></thead><tbody><tr><td><code>STUDENTS</code></td><td>学生基本信息（学号、姓名、性别、出生日期、专业）</td></tr><tr><td><code>MAJORS</code></td><td>专业信息（专业编号、专业名称）</td></tr><tr><td><code>COURSES</code></td><td>课程信息（课程编号、课程名称、学分）</td></tr><tr><td><code>ENROLLMENTS</code></td><td>选课记录（学号、课程编号、成绩）</td></tr></tbody></table><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>一句话总结</th></tr></thead><tbody><tr><td>数据库是什么</td><td>有组织的数据仓库，解决数据冗余、查询慢、并发冲突三大问题</td></tr><tr><td>关系型 vs 非关系型</td><td>关系型用表存数据（Oracle/MySQL），非关系型用键值/文档（Redis/MongoDB）</td></tr><tr><td>Oracle 定位</td><td>企业级关系型数据库的王者，银行、电信核心系统的首选</td></tr><tr><td>E-R 图</td><td>矩形（实体）+ 椭圆（属性）+ 菱形（关系），多对多要拆中间表</td></tr><tr><td>体系结构</td><td>实例（内存+进程）+ 数据库（物理文件），存储层次：表空间→段→区→块</td></tr><tr><td>主线案例</td><td>学生选课管理系统，贯穿全书</td></tr></tbody></table><h2 id="自检清单" tabindex="-1">自检清单 <a class="header-anchor" href="#自检清单" aria-label="Permalink to &quot;自检清单&quot;">​</a></h2><p>在进入下一章之前，确保你能回答：</p><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 数据库相比 Excel 解决了哪三个核心问题？</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 关系型数据库的核心特点是什么？</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Oracle 12c 中 &quot;c&quot; 代表什么？</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> E-R 图中，多对多关系在实际建表时怎么处理？</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Oracle 实例和数据库是什么关系？</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Oracle 的存储结构从小到大依次是什么？</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 本教程贯穿全书的实战案例是什么？</li></ul><blockquote><p><strong>下一章预告</strong>：动手安装 Oracle 12c，从下载到成功连接，每一步都有截图指引。</p></blockquote>`,78)])])}const _=r(n,[["render",i]]);export{k as __pageData,_ as default};
